// index.jsx
import React from 'react';
import ReactDOM from 'react-dom';
import { Table } from '@alifd/next';
import '@alifd/next/dist/next.css';

// Sample data
const dataSource = Array.from({ length: 5 }).map((_, idx) => ({
  id: 100306660940 + idx,
  time: 2000 + idx
}));

// App component
function App() {
  const handleSort = (dataIndex, order) => {
    // just log sorting for demo
    console.log('sort', dataIndex, order);
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>Table Sorting Demo</h3>
      <Table dataSource={dataSource} onSort={handleSort} style={{ width: '100%' }}>
        <Table.Column title="Id" dataIndex="id" sortable />
        <Table.Column title="Time" dataIndex="time" sortable />
      </Table>
    </div>
  );
}

// Render to DOM
ReactDOM.render(<App />, document.getElementById('root'));
